          "text": "QNB Bank Yatırım Yoluyla Türk Vatandaşlığını tercih eden birçok yatırımcı - 500.000 ABD Doları ile giriş yaptı ve yaklaşık 600.000 – 650.000 ABD Doları ile çıkış yaptı"
