          "type": "paragraph",
          "text": "ABD vatandaşları 180 gün içinde 90 güne kadar Türkiye'yi vizesiz ziyaret edebiliyor. Daha uzun süreli konaklamalar için oturma iznine ihtiyacınız vardır. Kısa süreli izin, yeni gelenler için en yaygın yoldur. Bunu turizme, mülk sahipliğine ya da aile bağlarına dayandırabilirsiniz. Mülkiyete dayalı izinler, büyük şehirlerde en az 200.000 $ değerinde bir ev gerektirir. Diğer illerde eşik 100.000 dolardır. Bazı ilçeler yeni yabancı ikamet izinlerine kapalı. E-İkamet sistemi üzerinden online başvuru yapıp randevuya katılıyorsunuz. Sağlık sigortası ve kira sözleşmesi veya tapu gereklidir. İzinler genellikle bir veya iki yıl süreyle geçerlidir ve yenilenebilir."
