          "type": "paragraph",
          "text": "欧洲吸引热爱历史、文化和适合步行的城市的退休人员。许多国家提供强大的医疗保健和良好的公共交通。一旦您居住，在申根区内旅行就很容易。一些国家提供适合退休人员的被动收入签证。然而，欧洲近年来收紧了一些计划。房地产不再符合葡萄牙黄金签证的资格。西班牙于2025年关闭黄金签证。生活成本高于拉丁美洲，尤其是首都。养老金税也可能更高。即便如此，欧洲仍然是许多美国人的首选。小城镇通常可以在成本和舒适度之间取得良好的平衡。以下是南欧的主要选择。"
