          "text": "西班牙的非盈利签证适合有被动收入的退休人员。每个月大约需要四倍的 IPREM 索引。西班牙拥有强大的医疗保健和庞大的外籍人士社区。巴伦西亚和太阳海岸很受美国人欢迎。希腊在著名的2026年退休指数中排名第一。其财务独立人士许可证适合有稳定收入的退休人员。收入门槛高于葡萄牙或西班牙。希腊拥有岛屿、阳光和雅典以外的较低成本。它还为外国养老金领取者制定了特殊的统一税收制度。这两个国家都适合想要地中海生活方式的退休人员。申请前请检查每个制度的当前条款。"
