      "text": "投资入籍项目在合资格资产、家庭成员范围、费用及法律保障方面各不相同。投入资金前，应比较投资途径和完整申请预算。本指南区分投资入籍与居留途径，并说明旅行权利和美国签证资格为何需要单独审查。投资不保证获得国籍。"
