          "text": "لقد ظهر طريق صندوق BES للحصول على الجنسية التركية عن طريق الاستثمار كبديل قوي للاستثمار العقاري. وبموجب القانون التركي، يجوز للمستثمرين التأهل من خلال تخصيص رأس المال لصناديق التقاعد الخاصة المعتمدة ضمن نظام BES."
