          "type": "paragraph",
          "text": "أحد الجوانب القانونية الرئيسية لمسار الإيداع البنكي هو أنه يجب تحويل الأموال المؤهلة إلى تركيا من خلال النظام المصرفي وتسجيلها بشكل صحيح من قبل البنك المتلقي."
