          "type": "paragraph",
          "text": "ومن الناحية العملية، لا يتطلب هذا أن تنشأ الأموال من حساب واحد أو ولاية قضائية واحدة، كما أنه لا يحظر البنوك الوسيطة أو هياكل التحويل الدولية القياسية. ومع ذلك، يجب أن يكون إطار النقل شفافًا وقابلاً للتفسير ومتسقًا مع الممارسات المصرفية العامة وممارسات الامتثال."
